using Numerics.Distributions;
using RMC.BestFit.Models;
using BestFitDataFrame = RMC.BestFit.Models.DataFrame;

namespace RMC.BestFit.Tests.Univariate;

/// <summary>
/// Unit tests for the <c>CompetingRisksModel</c> class.
/// Tests competing risks models for multiple flood-generating processes.
/// </summary>
/// <remarks>
/// <para>
/// Competing risks models are used when the annual maximum flood can be
/// generated by multiple independent processes (e.g., snowmelt, rainfall,
/// hurricanes). The observed annual maximum is the maximum of all competing
/// processes.
/// </para>
/// <para>
/// This differs from mixture models where data points come from different
/// populations. In competing risks, all processes compete each year to
/// produce the annual maximum.
/// </para>
/// </remarks>
[TestClass]
public class CompetingRisksModelTests
{
    #region Test Data Helper

    /// <summary>
    /// Creates a sample data frame with positive exact observations.
    /// </summary>
    private static BestFitDataFrame CreateSampleDataFrame()
    {
        var df = new BestFitDataFrame();
        var data = new List<ExactData>
        {
            new ExactData { Index = 1990, Value = 1500 },
            new ExactData { Index = 1991, Value = 2000 },
            new ExactData { Index = 1992, Value = 1800 },
            new ExactData { Index = 1993, Value = 2500 },
            new ExactData { Index = 1994, Value = 3000 },
            new ExactData { Index = 1995, Value = 2200 },
            new ExactData { Index = 1996, Value = 3500 },
            new ExactData { Index = 1997, Value = 2800 },
            new ExactData { Index = 1998, Value = 4000 },
            new ExactData { Index = 1999, Value = 3200 }
        };
        df.ExactSeries = new ExactSeries(data);
        return df;
    }

    /// <summary>
    /// Creates a data frame with extreme event characteristics.
    /// </summary>
    private static BestFitDataFrame CreateExtremeEventDataFrame()
    {
        var df = new BestFitDataFrame();
        var data = new List<ExactData>();

        // Regular events
        for (int i = 0; i < 20; i++)
        {
            data.Add(new ExactData { Index = 1980 + i, Value = 1000 + i * 100 });
        }

        // Extreme events (hurricane-like)
        data.Add(new ExactData { Index = 2000, Value = 8000 });
        data.Add(new ExactData { Index = 2005, Value = 10000 });
        data.Add(new ExactData { Index = 2010, Value = 12000 });

        df.ExactSeries = new ExactSeries(data);
        return df;
    }

    /// <summary>
    /// Creates a data frame with interval data.
    /// </summary>
    /// <remarks>
    /// <para>
    /// <c>IntervalData</c> requires a most-likely <c>Value</c> strictly between
    /// <c>LowerValue</c> and <c>UpperValue</c>; the object-initializer syntax
    /// <c>new IntervalData { Index = ..., LowerValue = ..., UpperValue = ... }</c> leaves
    /// <c>Value = 0</c>, which fails <c>IntervalData.Validate</c> and cascades to
    /// an invalid <c>DataFrame</c>. Use the 4-argument constructor
    /// <c>new IntervalData(index, lower, value, upper)</c> with a mid-point value so the
    /// frame validates and <c>CompetingRisksModel.SetDefaultParameters</c> populates
    /// <c>CompetingRisksModel.Parameters</c>.
    /// </para>
    /// </remarks>
    private static BestFitDataFrame CreateIntervalDataFrame()
    {
        var df = new BestFitDataFrame();
        // At least 4 exact data points are required because
        // <c>Numerics.Data.Statistics.Statistics.ProductMoments</c> returns
        // all-NaN when N &lt; 4 (see Statistics.cs ~line 481) — and NaN initial values
        // later cause Normal.ValidateParameters to throw "The mean must be a number".
        df.ExactSeries = new ExactSeries(new List<ExactData>
        {
            new ExactData { Index = 1990, Value = 2000 },
            new ExactData { Index = 1991, Value = 2500 },
            new ExactData { Index = 1992, Value = 3000 },
            new ExactData { Index = 1993, Value = 2200 },
            new ExactData { Index = 1994, Value = 2700 }
        });
        // 4-arg ctor: index, lowerValue, value (most-likely, must be strictly between lower and upper), upperValue.
        df.IntervalSeries = new IntervalSeries(new List<IntervalData>
        {
            new IntervalData(1800, 4000, 5000, 6000),
            new IntervalData(1850, 5000, 6500, 8000)
        });
        return df;
    }

    #endregion

    #region Constructor Tests

    /// <summary>Verifies that constructor empty constructor creates model.</summary>
    [TestMethod]
    public void Test_Constructor_EmptyConstructor_CreatesModel()
    {
        var model = new CompetingRisksModel();

        Assert.IsNotNull(model);
        Assert.IsTrue(model.UseSingleQuantile);
    }

    /// <summary>Verifies that constructor with distribution types sets components.</summary>
    [TestMethod]
    public void Test_Constructor_WithDistributionTypes_SetsComponents()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType>
        {
            UnivariateDistributionType.Normal,
            UnivariateDistributionType.Gumbel
        };

        var model = new CompetingRisksModel(df, types);

        Assert.IsNotNull(model.CompetingRisks);
        Assert.AreEqual(2, model.CompetingRisks.Distributions.Count);
        Assert.IsInstanceOfType(model.CompetingRisks.Distributions[0], typeof(Normal));
        Assert.IsInstanceOfType(model.CompetingRisks.Distributions[1], typeof(Gumbel));
    }

    /// <summary>Verifies that constructor with competing risks distribution clones distribution.</summary>
    [TestMethod]
    public void Test_Constructor_WithCompetingRisksDistribution_ClonesDistribution()
    {
        var df = CreateSampleDataFrame();
        var dist = new CompetingRisks(new UnivariateDistributionBase[]
        {
            new Normal(2000, 500),
            new Gumbel(2500, 600)
        });

        var model = new CompetingRisksModel(df, dist);

        Assert.IsNotNull(model.CompetingRisks);
        Assert.AreNotSame(dist, model.CompetingRisks);
    }

    /// <summary>Verifies that constructor throws when empty distribution types.</summary>
    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void Test_Constructor_EmptyDistributionTypes_ThrowsException()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType>();

        var model = new CompetingRisksModel(df, types);
    }

    /// <summary>Verifies that constructor throws when too many distributions.</summary>
    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void Test_Constructor_TooManyDistributions_ThrowsException()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType>
        {
            UnivariateDistributionType.Normal,
            UnivariateDistributionType.Gumbel,
            UnivariateDistributionType.GammaDistribution,
            UnivariateDistributionType.Weibull  // Fourth distribution exceeds limit
        };

        var model = new CompetingRisksModel(df, types);
    }

    /// <summary>Verifies that constructor throws when null distribution.</summary>
    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void Test_Constructor_NullDistribution_ThrowsException()
    {
        var df = CreateSampleDataFrame();
        CompetingRisks? dist = null;

        var model = new CompetingRisksModel(df, dist!);
    }

