    #region Property Tests

    /// <summary>Verifies that competing risks set and get.</summary>
    [TestMethod]
    public void Test_CompetingRisks_SetAndGet()
    {
        var model = new CompetingRisksModel();
        var dist = new CompetingRisks(new UnivariateDistributionBase[]
        {
            new Normal(1000, 200),
            new Gumbel(1500, 300)
        });

        model.CompetingRisks = dist;

        Assert.IsNotNull(model.CompetingRisks);
        Assert.AreEqual(2, model.CompetingRisks.Distributions.Count);
