    /// <summary>Verifies that use single quantile always returns true.</summary>
    [TestMethod]
    public void Test_UseSingleQuantile_AlwaysReturnsTrue()
    {
        var model = new CompetingRisksModel();

        Assert.IsTrue(model.UseSingleQuantile);

        // Setting to false should be ignored
        model.UseSingleQuantile = false;
        Assert.IsTrue(model.UseSingleQuantile);
    }

    /// <summary>Verifies that data frame set triggers parameter update.</summary>
    [TestMethod]
    public void Test_DataFrame_SetTriggersParameterUpdate()
    {
        var df1 = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType>
        {
            UnivariateDistributionType.Normal,
            UnivariateDistributionType.Gumbel
        };
        var model = new CompetingRisksModel(df1, types);
        int initialCount = model.NumberOfParameters;

        var df2 = CreateExtremeEventDataFrame();
        model.DataFrame = df2;

        // Parameters should still exist after data change
        Assert.IsNotNull(model.Parameters);
        Assert.AreEqual(initialCount, model.NumberOfParameters);
    }

