    #region SetDefaultParameters Tests

    /// <summary>Verifies that set default parameters creates parameters for all components.</summary>
    [TestMethod]
    public void Test_SetDefaultParameters_CreatesParametersForAllComponents()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType>
        {
            UnivariateDistributionType.Normal,  // 2 parameters
            UnivariateDistributionType.Gumbel   // 2 parameters
        };
        var model = new CompetingRisksModel(df, types);

        // Should have 4 total parameters (2 + 2)
        Assert.AreEqual(4, model.NumberOfParameters);
    }

    /// <summary>Verifies that set default parameters owner names are set.</summary>
    [TestMethod]
    public void Test_SetDefaultParameters_OwnerNamesAreSet()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType>
        {
            UnivariateDistributionType.Normal,
            UnivariateDistributionType.Gumbel
        };
        var model = new CompetingRisksModel(df, types);

        // First component parameters should have D1 owner
        Assert.AreEqual("D1", model.Parameters[0].OwnerName);
        Assert.AreEqual("D1", model.Parameters[1].OwnerName);

        // Second component parameters should have D2 owner
        Assert.AreEqual("D2", model.Parameters[2].OwnerName);
        Assert.AreEqual("D2", model.Parameters[3].OwnerName);
    }

