        var model = new CompetingRisksModel(df, types);

        foreach (var param in model.Parameters)
        {
            Assert.IsInstanceOfType(param.PriorDistribution, typeof(Uniform));
        }
    }

    /// <summary>Verifies that set default parameters three components.</summary>
    [TestMethod]
    public void Test_SetDefaultParameters_ThreeComponents()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType>
        {
            UnivariateDistributionType.Normal,      // 2 params
            UnivariateDistributionType.Gumbel,      // 2 params
            UnivariateDistributionType.GammaDistribution  // 2 params
        };
        var model = new CompetingRisksModel(df, types);

        Assert.AreEqual(6, model.NumberOfParameters);
        Assert.IsTrue(model.Parameters.Any(p => p.OwnerName == "D3"));
