    /// <summary>Verifies that pointwise prior log likelihood with quantile prior.</summary>
    [TestMethod]
    public void Test_PointwisePriorLogLikelihood_WithQuantilePrior()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType> { UnivariateDistributionType.Normal };
        var model = new CompetingRisksModel(df, types);
        model.EnableQuantilePriors = true;
        model.SetDefaultQuantilePriors();
        model.ProcessQuantilePriors();

        var parameters = model.Parameters.Select(p => p.Value).ToArray();
        var priors = model.PointwisePriorLogLikelihood(parameters);

        Assert.IsTrue(priors.Any(p => p.Type == PriorComponentType.QuantilePrior));
