    #region Validation Tests

    /// <summary>Verifies that validate returns true when valid model.</summary>
    [TestMethod]
    public void Test_Validate_ValidModel_ReturnsTrue()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType>
        {
            UnivariateDistributionType.Normal,
            UnivariateDistributionType.Gumbel
        };
        var model = new CompetingRisksModel(df, types);

        var (isValid, messages) = model.Validate();

        Assert.IsTrue(isValid, $"Validation failed: {string.Join(", ", messages)}");
    }

    /// <summary>Verifies that validate returns false when null data frame.</summary>
    [TestMethod]
    public void Test_Validate_NullDataFrame_ReturnsFalse()
    {
        var model = new CompetingRisksModel();
        model.DataFrame = null!;

        var (isValid, messages) = model.Validate();

        Assert.IsFalse(isValid);
        Assert.IsTrue(messages.Any(m => m.Contains("Data frame")));
    }

    /// <summary>Verifies that validate returns false when null competing risks.</summary>
    [TestMethod]
    public void Test_Validate_NullCompetingRisks_ReturnsFalse()
    {
        var df = CreateSampleDataFrame();
        var model = new CompetingRisksModel();
        model.DataFrame = df;
        model.CompetingRisks = null;

        var (isValid, messages) = model.Validate();

        Assert.IsFalse(isValid);
        Assert.IsTrue(messages.Any(m => m.Contains("Competing risks")));
    }

    /// <summary>Verifies that validate returns false when too many components.</summary>
    [TestMethod]
    public void Test_Validate_TooManyComponents_ReturnsFalse()
    {
        var df = CreateSampleDataFrame();
        var model = new CompetingRisksModel();
        model.DataFrame = df;

        // Create distribution with 4 components (exceeds limit of 3)
        var dists = new UnivariateDistributionBase[]
        {
            new Normal(100, 10),
            new Normal(200, 20),
            new Normal(300, 30),
            new Normal(400, 40)
        };
        model.CompetingRisks = new CompetingRisks(dists);

        var (isValid, messages) = model.Validate();

        Assert.IsFalse(isValid);
        Assert.IsTrue(messages.Any(m => m.Contains("3")));
    }

    /// <summary>Verifies that validate returns true when single component.</summary>
    [TestMethod]
    public void Test_Validate_SingleComponent_ReturnsTrue()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType> { UnivariateDistributionType.Gumbel };
        var model = new CompetingRisksModel(df, types);

        var (isValid, messages) = model.Validate();

        Assert.IsTrue(isValid, $"Validation failed: {string.Join(", ", messages)}");
    }

    /// <summary>Verifies that validate returns true when three components.</summary>
    [TestMethod]
    public void Test_Validate_ThreeComponents_ReturnsTrue()
    {
