    }

    /// <summary>Verifies that set parameter values updates distribution.</summary>
    [TestMethod]
    public void Test_SetParameterValues_UpdatesDistribution()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType> { UnivariateDistributionType.Normal };
        var model = new CompetingRisksModel(df, types);

        var newValues = new double[] { 3000.0, 500.0 };
        model.SetParameterValues(newValues);

        // Distribution parameters should be updated
        var normal = (Normal)model.CompetingRisks!.Distributions[0];
        Assert.AreEqual(3000.0, normal.Mu, 1e-10);
        Assert.AreEqual(500.0, normal.Sigma, 1e-10);
    }

