    #region Jeffreys Prior Tests

    /// <summary>Verifies that jeffreys prior affects prior log likelihood.</summary>
    [TestMethod]
    public void Test_JeffreysPrior_AffectsPriorLogLikelihood()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType> { UnivariateDistributionType.Normal };
        var model = new CompetingRisksModel(df, types);

        var parameters = model.Parameters.Select(p => p.Value).ToArray();

        model.UseJeffreysRuleForScale = false;
        double priorNoJeffreys = model.PriorLogLikelihood(parameters);

        model.UseJeffreysRuleForScale = true;
        double priorWithJeffreys = model.PriorLogLikelihood(parameters);

        // Jeffreys prior adds -log(scale) term
        Assert.AreNotEqual(priorNoJeffreys, priorWithJeffreys);
    }

    /// <summary>Verifies that jeffreys prior gamma distribution uses first parameter.</summary>
    [TestMethod]
    public void Test_JeffreysPrior_GammaDistribution_UsesFirstParameter()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType> { UnivariateDistributionType.GammaDistribution };
        var model = new CompetingRisksModel(df, types);
        model.UseJeffreysRuleForScale = true;

        var parameters = model.Parameters.Select(p => p.Value).ToArray();
        var priors = model.PointwisePriorLogLikelihood(parameters);

        // Should have Jeffreys scale prior for Gamma's first parameter
        Assert.IsTrue(priors.Any(p => p.Type == PriorComponentType.JeffreysScalePrior));
    }

    /// <summary>Verifies that jeffreys prior weibull uses first parameter.</summary>
    [TestMethod]
    public void Test_JeffreysPrior_Weibull_UsesFirstParameter()
    {
        var df = CreateSampleDataFrame();
        var types = new List<UnivariateDistributionType> { UnivariateDistributionType.Weibull };
        var model = new CompetingRisksModel(df, types);
        model.UseJeffreysRuleForScale = true;

        var parameters = model.Parameters.Select(p => p.Value).ToArray();
        var priors = model.PointwisePriorLogLikelihood(parameters);

        // Should have Jeffreys scale prior for Weibull's first parameter (scale)
        Assert.IsTrue(priors.Any(p => p.Type == PriorComponentType.JeffreysScalePrior));
    }

    #endregion

